class Solution:
    def wiggleMaxLength(self, nums: List[int]) -> int:
        if len(nums) < 2:
            return len(nums)
        length = 1
        prev_diff = 0
        for i in range(1, len(nums)):
            diff = nums[i] - nums[i - 1]
            if diff > 0 and prev_diff <= 0:
                length += 1
                prev_diff = diff
            elif diff < 0 and prev_diff >= 0:
                length += 1
                prev_diff = diff
        return length

