int wiggleMaxLength(int* nums, int numsSize) {
    if (numsSize < 2) return numsSize;
    int length = 1;
    int prevDiff = 0;
    for (int i = 1; i < numsSize; ++i) {
        int diff = nums[i] - nums[i - 1];
        if (diff > 0 && prevDiff <= 0) {
            ++length;
            prevDiff = diff;
        } else if (diff < 0 && prevDiff >= 0) {
            ++length;
            prevDiff = diff;
        }
    }
    return length;
}

